usage:
import { Compare } from "./Compare";
import "./Compare.css";

<Compare
  labels
  corner={20}
/>

notes:
/* TWO PICTURES, ONE FRAME. The x-ray and the colour photo are the
   same scene at the same size, so the halves line up exactly. */

/* the line is jelly: its ends chase the knob on a soft spring,
   and the picture is cut along the same curve */
ends.v += ((x - ends.x) * 620 - ends.v * 44) * dt;
clip-path: path("M0 0 L{x-b} 0 Q{x+b} {h/2} {x-b} {h} L0 {h} Z");
